#include <string>
#include <vector>
#include <cstring>
#include <openssl/hmac.h>
#include <openssl/evp.h>
#include <stdint.h>
#include <arpa/inet.h>

struct SessionCtx {
    std::string username;
    std::string domain;
    std::vector<uint8_t> session_key;
    bool authenticated;
    int privilege_level; // 0=none, 1=user, 2=admin
};

// Parse a TLV (Type-Length-Value) authorization token
// Format: [type:2][length:2][value:length] repeated
// Returns the privilege level encoded in the token
int parse_auth_token(const uint8_t* token, size_t token_len, SessionCtx& ctx) {
    size_t offset = 0;
    int privilege = 0;

    // Token must start with magic bytes
    if (token_len < 8) return -1;
    if (memcmp(token, "AUTH", 4) != 0) return -1;

    // Read number of TLV entries (uint16 at offset 4)
    uint16_t num_entries = ntohs(*(const uint16_t*)(token + 4));
    // Read total declared payload length (uint16 at offset 6)
    uint16_t declared_len = ntohs(*(const uint16_t*)(token + 6));

    // Validate declared length against actual buffer
    if ((size_t)declared_len + 8 > token_len) return -1;

    offset = 8;

    for (uint16_t i = 0; i < num_entries; i++) {
        if (offset + 4 > token_len) return -1;

        uint16_t tlv_type = ntohs(*(const uint16_t*)(token + offset));
        uint16_t tlv_len = ntohs(*(const uint16_t*)(token + offset + 2));

        offset += 4;

        // Bounds check: ensure we don't read past the actual buffer
        if (offset + (size_t)tlv_len > token_len) return -1;

        switch (tlv_type) {
            case 0x0001: // Username
                if (tlv_len > 0 && tlv_len <= 255) {
                    ctx.username = std::string((const char*)(token + offset), tlv_len);
                }
                break;
            case 0x0002: // Domain
                if (tlv_len > 0 && tlv_len <= 255) {
                    ctx.domain = std::string((const char*)(token + offset), tlv_len);
                }
                break;
            case 0x0003: // Privilege level
                if (tlv_len == 4) {
                    privilege = ntohl(*(const uint32_t*)(token + offset));
                }
                break;
            case 0x0004: // HMAC signature (must be last)
                // Verify HMAC over everything before this TLV
                if (tlv_len == 32 && ctx.session_key.size() == 32) {
                    uint8_t computed[32];
                    unsigned int hmac_len = 32;
                    size_t signed_portion = offset - 4; // everything up to this TLV header
                    HMAC(EVP_sha256(), ctx.session_key.data(), 32,
                         token, signed_portion, computed, &hmac_len);
                    if (CRYPTO_memcmp(computed, token + offset, 32) == 0) {
                        ctx.authenticated = true;
                        ctx.privilege_level = privilege;
                    }
                }
                break;
        }

        offset += (size_t)tlv_len;
    }

    return ctx.authenticated ? privilege : -1;
}

// Validate and apply a privilege escalation request
// The request contains a new auth token that should be re-validated
bool process_reauth(const uint8_t* request, size_t request_len, SessionCtx& ctx) {
    if (request_len < 4) return false;

    // First 4 bytes: offset into request where new token starts
    uint32_t token_offset = ntohl(*(const uint32_t*)request);

    // Calculate remaining length for the token
    if (token_offset >= request_len) return false;
    size_t remaining = request_len - token_offset;

    // Parse the embedded auth token
    SessionCtx new_ctx;
    new_ctx.session_key = ctx.session_key;
    new_ctx.authenticated = false;
    new_ctx.privilege_level = 0;

    int result = parse_auth_token(request + token_offset, remaining, new_ctx);

    if (result > 0 && new_ctx.authenticated) {
        // Only allow privilege escalation if current session is authenticated
        if (ctx.authenticated) {
            ctx.privilege_level = new_ctx.privilege_level;
            return true;
        }
    }
    return false;
}

// Network packet handler - receives raw bytes from socket
void handle_packet(const std::vector<uint8_t>& packet, SessionCtx& ctx) {
    if (packet.size() < 2) return;

    uint8_t msg_type = packet[0];
    uint8_t flags = packet[1];

    switch (msg_type) {
        case 0x01: // Initial auth
            parse_auth_token(packet.data() + 2, packet.size() - 2, ctx);
            break;
        case 0x02: // Re-auth / privilege change
            process_reauth(packet.data() + 2, packet.size() - 2, ctx);
            break;
        case 0x03: // Admin command (requires privilege_level >= 2)
            if (ctx.authenticated && ctx.privilege_level >= 2) {
                // Execute admin command...
            }
            break;
    }
}
